() => {
  const main = document.querySelector('main') || document.body;
  // find hero heading
  const h1 = document.querySelector('h1');
  const hero = h1 ? h1.closest('section') || h1.parentElement.parentElement : null;
  return {
    heroTag: hero ? hero.tagName : null,
    heroClass: hero ? hero.className : null,
    heroParentTag: hero ? hero.parentElement.tagName : null,
    heroNextTag: hero && hero.nextElementSibling ? hero.nextElementSibling.tagName + ' ' + hero.nextElementSibling.className : null,
    bodyChildren: Array.from(document.body.children).map(c=>c.tagName+'.'+c.className).slice(0,10)
  };
}

() => {
  const secs = Array.from(document.body.children).filter(c=>c.tagName==='SECTION');
  const overview = secs[1]; // first content section after hero
  return {
    outerHTML: overview.outerHTML.slice(0, 600)
  };
}

