() => {
  const pro = document.querySelector('#pricing .relative');
  const oldBadge = pro.querySelector('span.absolute');
  const wrapper = document.createElement('div');
  wrapper.className = 'absolute -top-3 inset-x-0 flex justify-center';
  wrapper.innerHTML = '<span class="inline-flex items-center gap-1 rounded-full bg-blue-500 px-3 py-1 text-xs font-semibold text-white shadow">Recommended</span>';
  pro.replaceChild(wrapper, oldBadge);
  return { replaced: true };
}

